65:     if (typeof totalSeconds !== 'number' || isNaN(totalSeconds) || totalSeconds < 0 || !isFinite(totalSeconds)) {
66:       return '00:00:00';
67:     }
68:     var sec = Math.floor(totalSeconds);
69:     var hours = Math.floor(sec / 3600);
