#!/usr/bin/env node
/**
 * tests/adversarial-m5-stress.js - Empirical Adversarial Stress Suite for Milestone 5
 * 
 * Challenger Agent: challenger_m5_1
 * Role: Empirical Challenger (Critic & Specialist)
 * Target: PlayerController & PlayerOSDController Robustness & Data Stress
 * 
 * Stress Dimensions:
 * 1. Rapid concurrent stream load requests (fast switching before network resolves)
 * 2. Rapid seeking hammering (50 seek ops in 200ms) & boundary clamping
 * 3. Teardown memory leak audit (zero running timers, listeners, unreleased media elements)
 * 4. Corrupted localStorage resume position fuzzing (NaN, null, string, negative, future, Infinity)
 * 5. Stream stall and 15000ms watchdog timeout verification
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

// 2. Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(category, testName, fn) {
  totalChecks++;
  const idStr = totalChecks.toString().padStart(2, '0');
  const label = `[ADV-M5-${idStr}] [${category}] ${testName}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    failureList.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.gray}Error: ${err.message}${C.reset}`);
  }
}

function sleep(ms) {
  return new Promise(function (resolve) { setTimeout(resolve, ms); });
}

// -----------------------------------------------------------------------------
// 3. Layout & Media Mocks
// -----------------------------------------------------------------------------
function installLayoutMock(window) {
  function makeRect(left, top, width, height) {
    return {
      left: left, top: top, width: width, height: height,
      right: left + width, bottom: top + height, x: left, y: top
    };
  }
  window.Element.prototype.getBoundingClientRect = function () {
    if (this.style && this.style.display === 'none') return makeRect(0, 0, 0, 0);
    const id = this.id;
    if (id === 'osd-rewind-btn') return makeRect(815, 960, 54, 54);
    if (id === 'osd-play-btn') return makeRect(893, 953, 68, 68);
    if (id === 'osd-forward-btn') return makeRect(985, 960, 54, 54);
    if (id === 'osd-subtitles-btn') return makeRect(1420, 960, 180, 52);
    if (id === 'osd-server-btn') return makeRect(1616, 960, 180, 52);
    if (id === 'player-error-retry-btn') return makeRect(740, 580, 180, 52);
    if (id === 'player-error-switch-btn') return makeRect(940, 580, 160, 52);
    if (id === 'player-error-exit-btn') return makeRect(1120, 580, 160, 52);
    return makeRect(96, 100, 100, 40);
  };
  window.Element.prototype.scrollIntoView = function () {};
  window.Element.prototype.scrollTo = function () {};
}

function installVideoMock(window) {
  const proto = window.HTMLMediaElement.prototype;

  function getState(el) {
    if (!el._mediaState) {
      el._mediaState = {
        currentTime: 0,
        duration: 7200,
        paused: true,
        ended: false,
        seeking: false,
        readyState: 0,
        bufferedRanges: [[0, 0]],
        playbackRate: 1.0,
        volume: 1.0,
        muted: false,
        textTracks: [],
        error: null,
        src: '',
        loadCount: 0,
        pauseCount: 0,
        playCount: 0
      };
    }
    return el._mediaState;
  }

  Object.defineProperty(proto, 'currentTime', {
    get: function () { return getState(this).currentTime; },
    set: function (val) {
      const s = getState(this);
      const num = Number(val);
      if (isNaN(num) || !isFinite(num)) {
        throw new TypeError("Failed to set 'currentTime' on 'HTMLMediaElement': The provided double value is non-finite.");
      }
      const clamped = Math.max(0, Math.min(s.duration, num));
      s.currentTime = clamped;
      s.seeking = true;
      this.dispatchEvent(new window.Event('seeking'));
      s.seeking = false;
      this.dispatchEvent(new window.Event('seeked'));
      this.dispatchEvent(new window.Event('timeupdate'));
    },
    configurable: true
  });

  Object.defineProperty(proto, 'duration', {
    get: function () { return getState(this).duration; },
    set: function (val) { getState(this).duration = Number(val) || 0; },
    configurable: true
  });

  Object.defineProperty(proto, 'paused', {
    get: function () { return getState(this).paused; },
    configurable: true
  });

  Object.defineProperty(proto, 'ended', {
    get: function () { return getState(this).ended; },
    configurable: true
  });

  Object.defineProperty(proto, 'readyState', {
    get: function () { return getState(this).readyState; },
    configurable: true
  });

  Object.defineProperty(proto, 'buffered', {
    get: function () {
      const ranges = getState(this).bufferedRanges;
      return {
        length: ranges.length,
        start: function (i) { return ranges[i][0]; },
        end: function (i) { return ranges[i][1]; }
      };
    },
    configurable: true
  });

  Object.defineProperty(proto, 'error', {
    get: function () { return getState(this).error; },
    configurable: true
  });

  proto.play = function () {
    const s = getState(this);
    s.paused = false;
    s.ended = false;
    s.readyState = 4;
    s.playCount++;
    this.dispatchEvent(new window.Event('play'));
    this.dispatchEvent(new window.Event('playing'));
    return Promise.resolve();
  };

  proto.pause = function () {
    const s = getState(this);
    s.paused = true;
    s.pauseCount++;
    this.dispatchEvent(new window.Event('pause'));
  };

  proto.load = function () {
    const s = getState(this);
    s.currentTime = 0;
    s.ended = false;
    s.loadCount++;
    this.dispatchEvent(new window.Event('loadstart'));
  };

  proto.canPlayType = function () { return 'probably'; };

  proto._setDuration = function (d) { getState(this).duration = d; };
  proto._simulateTimeUpdate = function (t) {
    const s = getState(this);
    s.currentTime = Math.max(0, Math.min(s.duration, t));
    this.dispatchEvent(new window.Event('timeupdate'));
  };
  proto._simulateWaiting = function () {
    getState(this).readyState = 2;
    this.dispatchEvent(new window.Event('waiting'));
  };
  proto._simulatePlaying = function () {
    getState(this).readyState = 4;
    getState(this).paused = false;
    this.dispatchEvent(new window.Event('playing'));
  };
  proto._simulateCanPlay = function () {
    getState(this).readyState = 4;
    this.dispatchEvent(new window.Event('canplay'));
  };
}

let activeHlsInstances = [];
function installHlsMock(window) {
  activeHlsInstances = [];
  function MockHls(config) {
    this.config = config || {};
    this.media = null;
    this.url = null;
    this.destroyed = false;
    this._listeners = {};
    this.levels = [
      { bitrate: 5000000, width: 1920, height: 1080, name: '1080p' }
    ];
    this._currentLevel = -1;
    this.audioTracks = [{ name: 'English', lang: 'en', default: true }];
    this.subtitleTracks = [{ id: 0, lang: 'en', name: 'English' }];
    activeHlsInstances.push(this);
  }

  MockHls.prototype.on = function (event, cb) {
    if (!this._listeners[event]) this._listeners[event] = [];
    this._listeners[event].push(cb);
  };
  MockHls.prototype.off = function (event, cb) {
    if (!this._listeners[event]) return;
    this._listeners[event] = this._listeners[event].filter(fn => fn !== cb);
  };
  MockHls.prototype.trigger = function (event, data) {
    const list = this._listeners[event] || [];
    for (let i = 0; i < list.length; i++) {
      try { list[i](event, data || {}); } catch (_) {}
    }
  };
  MockHls.prototype.attachMedia = function (mediaElement) {
    this.media = mediaElement;
    this.trigger(MockHls.Events.MEDIA_ATTACHED, { media: mediaElement });
  };
  MockHls.prototype.detachMedia = function () {
    this.media = null;
    this.trigger(MockHls.Events.MEDIA_DETACHED, {});
  };
  MockHls.prototype.loadSource = function (url) {
    this.url = url;
    this.trigger(MockHls.Events.MANIFEST_LOADING, { url });
    const self = this;
    setTimeout(function () {
      if (!self.destroyed) {
        self.trigger(MockHls.Events.MANIFEST_PARSED, { levels: self.levels });
      }
    }, 5);
  };
  MockHls.prototype.startLoad = function () { this.loading = true; };
  MockHls.prototype.stopLoad = function () { this.loading = false; };
  MockHls.prototype.recoverMediaError = function () {};
  MockHls.prototype.destroy = function () {
    this.destroyed = true;
    this.media = null;
    this.url = null;
    this._listeners = {};
  };
  MockHls.isSupported = function () { return true; };
  MockHls.Events = {
    MANIFEST_LOADING: 'hlsManifestLoading',
    MANIFEST_LOADED: 'hlsManifestLoaded',
    MANIFEST_PARSED: 'hlsManifestParsed',
    LEVEL_SWITCHED: 'hlsLevelSwitched',
    ERROR: 'hlsError',
    MEDIA_ATTACHED: 'hlsMediaAttached',
    MEDIA_DETACHED: 'hlsMediaDetached',
    SUBTITLE_TRACK_SWITCH: 'hlsSubtitleTrackSwitch'
  };
  MockHls.ErrorTypes = {
    NETWORK_ERROR: 'networkError',
    MEDIA_ERROR: 'mediaError',
    OTHER_ERROR: 'otherError'
  };
  MockHls.ErrorDetails = {
    BUFFER_STALLED_ERROR: 'bufferStalledError'
  };
  window.Hls = MockHls;
}

// -----------------------------------------------------------------------------
// 4. Test Harness Creator
// -----------------------------------------------------------------------------
function createStressHarness(options) {
  const opts = options || {};
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const navPath = path.resolve(__dirname, '../app/js/navigation.js');
  const tmdbPath = path.resolve(__dirname, '../app/js/tmdb.js');
  const homePath = path.resolve(__dirname, '../app/js/views/home.js');
  const catalogPath = path.resolve(__dirname, '../app/js/views/catalog.js');
  const searchPath = path.resolve(__dirname, '../app/js/views/search.js');
  const detailsPath = path.resolve(__dirname, '../app/js/views/details.js');
  const playerPath = path.resolve(__dirname, '../app/js/player.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#home',
    runScripts: 'outside-only'
  });
  const window = dom.window;

  // Virtual Clock
  let virtualTime = 0;
  let timerSeq = 1;
  const virtualTimers = new Map();
  const activeIntervals = new Set();
  const activeTimeouts = new Set();

  const origSetTimeout = window.setTimeout.bind(window);
  const origClearTimeout = window.clearTimeout.bind(window);
  const origSetInterval = window.setInterval.bind(window);
  const origClearInterval = window.clearInterval.bind(window);

  window.advanceClock = function (ms) {
    virtualTime += ms;
    let firedAny = true;
    while (firedAny) {
      firedAny = false;
      const readyTimers = [];
      virtualTimers.forEach((timer, id) => {
        if (timer.fireAt <= virtualTime) {
          readyTimers.push({ id, ...timer });
        }
      });
      readyTimers.sort((a, b) => a.fireAt - b.fireAt);
      for (const t of readyTimers) {
        if (!virtualTimers.has(t.id)) continue;
        firedAny = true;
        if (t.interval) {
          t.fireAt += t.interval;
          virtualTimers.set(t.id, t);
        } else {
          virtualTimers.delete(t.id);
          activeTimeouts.delete(t.id);
        }
        try {
          t.callback();
        } catch (err) {
          // ignore or log
        }
      }
    }
  };

  window.setTimeout = function (callback, delay) {
    const d = Number(delay) || 0;
    if (d >= 200) {
      const id = timerSeq++;
      virtualTimers.set(id, { callback, fireAt: virtualTime + d, interval: null });
      activeTimeouts.add(id);
      return id;
    }
    const realId = origSetTimeout(callback, delay);
    activeTimeouts.add(realId);
    return realId;
  };

  window.clearTimeout = function (id) {
    activeTimeouts.delete(id);
    if (virtualTimers.has(id)) {
      virtualTimers.delete(id);
      return;
    }
    return origClearTimeout(id);
  };

  window.setInterval = function (callback, delay) {
    const d = Number(delay) || 0;
    if (d >= 200) {
      const id = timerSeq++;
      virtualTimers.set(id, { callback, fireAt: virtualTime + d, interval: d });
      activeIntervals.add(id);
      return id;
    }
    const realId = origSetInterval(callback, delay);
    activeIntervals.add(realId);
    return realId;
  };

  window.clearInterval = function (id) {
    activeIntervals.delete(id);
    if (virtualTimers.has(id)) {
      virtualTimers.delete(id);
      return;
    }
    return origClearInterval(id);
  };

  window.getTimerStats = function () {
    return {
      virtualTimersCount: virtualTimers.size,
      activeIntervalsCount: activeIntervals.size,
      activeTimeoutsCount: activeTimeouts.size
    };
  };

  installLayoutMock(window);
  installVideoMock(window);
  installHlsMock(window);

  // Custom fetch mock
  window.fetch = function (url, fetchOpts) {
    if (typeof opts.customFetch === 'function') {
      return opts.customFetch(url, fetchOpts);
    }
    const urlStr = String(url);
    if (urlStr.includes('/api/stream')) {
      const params = new URL(urlStr, 'http://127.0.0.1:8088').searchParams;
      const tmdbId = params.get('tmdbId');
      const server = params.get('server') || 'secret';
      return Promise.resolve({
        ok: true,
        status: 200,
        json: () => Promise.resolve({
          success: true,
          streamUrl: `http://127.0.0.1:8088/hls/proxy?url=https%3A%2F%2Flightspeed.st%2F${tmdbId}.m3u8`,
          originalUrl: `https://lightspeed.st/${tmdbId}.m3u8`,
          server: server,
          subtitles: [{ label: 'English', srclang: 'en', src: 'http://127.0.0.1:8088/proxy/sub?url=en.srt' }]
        })
      });
    }
    if (urlStr.includes('/api/servers')) {
      return Promise.resolve({
        ok: true,
        status: 200,
        json: () => Promise.resolve({
          servers: [{ name: 'secret' }, { name: 'Nebula' }, { name: 'Lisbon' }]
        })
      });
    }
    return Promise.resolve({ ok: true, status: 200, json: () => Promise.resolve({}) });
  };

  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(tmdbPath, 'utf8'));
  window.eval(fs.readFileSync(homePath, 'utf8'));
  window.eval(fs.readFileSync(catalogPath, 'utf8'));
  window.eval(fs.readFileSync(searchPath, 'utf8'));
  window.eval(fs.readFileSync(detailsPath, 'utf8'));
  window.eval(fs.readFileSync(playerPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  if (window.CinejoyApp && typeof window.CinejoyApp.init === 'function') {
    window.CinejoyApp.init();
  }

  return {
    dom: dom,
    window: window,
    player: window.PlayerController,
    osd: window.PlayerOSDController,
    video: window.document.getElementById('main-video-player'),
    nav: window.SpatialNav,
    getTimerStats: window.getTimerStats,
    advanceClock: window.advanceClock
  };
}

// -----------------------------------------------------------------------------
// 5. Adversarial Test Suites
// -----------------------------------------------------------------------------
async function runAdversarialSuites() {
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}   MILESTONE 5 EMPIRICAL ADVERSARIAL STRESS SUITE (challenger_m5_1)${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

  // ===========================================================================
  // BATCH 1: Rapid Concurrent Stream Load Requests (Race & Overlap Stress)
  // ===========================================================================
  console.log(`${C.bold}▶ BATCH 1: Rapid Concurrent Stream Load Requests${C.reset}`);

  await check('CONCURRENCY', 'Rapid 5-stream cascade resolution concurrency', async () => {
    let fetchCount = 0;
    const harness = createStressHarness({
      customFetch: (url) => {
        fetchCount++;
        const urlStr = String(url);
        const params = new URL(urlStr, 'http://127.0.0.1:8088').searchParams;
        const id = params.get('tmdbId');
        // Introduce varying network latencies
        const delay = id === '1005' ? 10 : 30;
        return new Promise((resolve) => {
          setTimeout(() => {
            resolve({
              ok: true,
              status: 200,
              json: () => Promise.resolve({
                success: true,
                streamUrl: `http://127.0.0.1:8088/hls/proxy?url=movie_${id}.m3u8`,
                originalUrl: `https://lightspeed.st/movie_${id}.m3u8`,
                server: 'secret',
                subtitles: []
              })
            });
          }, delay);
        });
      }
    });

    // Fire 5 rapid loadStream calls without awaiting
    const p1 = harness.player.loadStream({ tmdbId: 1001, type: 'movie' });
    const p2 = harness.player.loadStream({ tmdbId: 1002, type: 'movie' });
    const p3 = harness.player.loadStream({ tmdbId: 1003, type: 'movie' });
    const p4 = harness.player.loadStream({ tmdbId: 1004, type: 'movie' });
    const p5 = harness.player.loadStream({ tmdbId: 1005, type: 'movie' });

    await Promise.all([p1, p2, p3, p4, p5]);
    await sleep(50);

    // Final active item MUST be the last requested item (1005)
    assert.strictEqual(harness.player.currentItem.tmdbId, 1005, 'Final active item must be 1005');
    assert(harness.player.streamUrl.includes('movie_1005.m3u8'), 'Final streamUrl must be movie_1005');
  });

  await check('CONCURRENCY', 'Earlier network failure does not crash newer pending stream', async () => {
    let callIdx = 0;
    const harness = createStressHarness({
      customFetch: (url) => {
        callIdx++;
        const currentIdx = callIdx;
        if (currentIdx === 1) {
          // Stream 1 fails with 500 error after 20ms
          return new Promise((resolve) => {
            setTimeout(() => {
              resolve({
                ok: false,
                status: 500,
                text: () => Promise.resolve('Server Error')
              });
            }, 20);
          });
        } else {
          // Stream 2 succeeds after 40ms
          return new Promise((resolve) => {
            setTimeout(() => {
              resolve({
                ok: true,
                status: 200,
                json: () => Promise.resolve({
                  success: true,
                  streamUrl: 'http://127.0.0.1:8088/hls/proxy?url=valid_stream.m3u8',
                  originalUrl: 'https://lightspeed.st/valid_stream.m3u8',
                  server: 'secret',
                  subtitles: []
                })
              });
            }, 40);
          });
        }
      }
    });

    const p1 = harness.player.loadStream({ tmdbId: 2001, type: 'movie' }).catch(() => {});
    await sleep(5);
    const p2 = harness.player.loadStream({ tmdbId: 2002, type: 'movie' });

    await Promise.all([p1, p2]);
    await sleep(60);

    // Stream 2 should have succeeded, player state must NOT be ERROR
    assert.notStrictEqual(harness.player.state, 'ERROR', 'Player state must not be ERROR from discarded stream 1');
    assert.strictEqual(harness.player.currentItem.tmdbId, 2002, 'Current item should be stream 2 (2002)');
  });

  await check('CONCURRENCY', 'Destroy called mid-flight during slow stream resolution', async () => {
    let aborted = false;
    const harness = createStressHarness({
      customFetch: (url, opts) => {
        return new Promise((resolve, reject) => {
          const timer = setTimeout(() => {
            resolve({
              ok: true,
              status: 200,
              json: () => Promise.resolve({
                success: true,
                streamUrl: 'http://127.0.0.1:8088/hls/proxy?url=slow.m3u8',
                server: 'secret',
                subtitles: []
              })
            });
          }, 100);
          if (opts && opts.signal) {
            opts.signal.addEventListener('abort', () => {
              clearTimeout(timer);
              aborted = true;
              const err = new Error('AbortError');
              err.name = 'AbortError';
              reject(err);
            });
          }
        });
      }
    });

    const p = harness.player.loadStream({ tmdbId: 3001, type: 'movie' }).catch(() => {});
    await sleep(15);
    harness.player.destroy();
    await sleep(120);

    assert.strictEqual(harness.player.state, 'IDLE', 'Player state must remain IDLE after destroy');
    const errDialog = harness.window.document.getElementById('player-error-dialog');
    assert.notStrictEqual(errDialog.style.display, 'flex', 'Error dialog must NOT pop up after player was destroyed');
  });

  await check('CONCURRENCY', 'Rapid 10x server switching preserves playhead position', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 4001, type: 'movie' });
    harness.video._setDuration(7200);
    harness.video.currentTime = 1850;

    // Rapidly switch servers 10 times in sequence
    const servers = ['Nebula', 'Lisbon', 'Solara', 'Athens', 'secret', 'Nebula', 'Lisbon', 'Solara', 'Athens', 'secret'];
    for (const srv of servers) {
      await harness.player.switchServer(srv);
    }
    await sleep(20);

    assert.strictEqual(harness.player.activeServer, 'secret');
    assert.strictEqual(harness.video.currentTime, 1850, 'Current time 1850s must be preserved across rapid server switches');
  });

  // ===========================================================================
  // BATCH 2: Rapid Seeking Hammering & Boundary Clamping
  // ===========================================================================
  console.log(`\n${C.bold}▶ BATCH 2: Rapid Seeking Hammering & Boundary Clamping${C.reset}`);

  await check('SEEK_HAMMER', '50 seek operations within 200ms without exception', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 5001, type: 'movie' });
    harness.video._setDuration(3600);
    harness.video.currentTime = 500;

    // Hammer seek alternating +10 and -10
    for (let i = 0; i < 50; i++) {
      harness.player.seek(i % 2 === 0 ? 10 : -10);
    }

    assert.strictEqual(harness.video.currentTime, 500, 'Net seek delta after 50 balanced seeks should return to 500s');
    assert.notStrictEqual(harness.player.state, 'ERROR');
  });

  await check('SEEK_CLAMP', 'Extreme negative seek clamps precisely to 0 without underflow', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 5002, type: 'movie' });
    harness.video._setDuration(3600);
    harness.video.currentTime = 25;

    harness.player.seek(-9999999);
    assert.strictEqual(harness.video.currentTime, 0, 'Negative seek must clamp to 0');
    assert(harness.video.currentTime >= 0, 'CurrentTime cannot be negative');
  });

  await check('SEEK_CLAMP', 'Extreme positive seek clamps precisely to duration without overflow', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 5003, type: 'movie' });
    harness.video._setDuration(5400);
    harness.video.currentTime = 100;

    harness.player.seek(9999999);
    assert.strictEqual(harness.video.currentTime, 5400, 'Positive seek must clamp to duration (5400)');
  });

  await check('SEEK_FUZZ', 'Fuzzing seek() with non-finite and corrupt types does not crash', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 5004, type: 'movie' });
    harness.video._setDuration(3600);
    harness.video.currentTime = 300;

    // Fuzz inputs
    const badDeltas = [NaN, Infinity, -Infinity, 'corrupted', null, undefined, {}, []];
    for (const bad of badDeltas) {
      try {
        harness.player.seek(bad);
      } catch (err) {
        assert.fail(`seek(${bad}) threw unhandled exception: ${err.message}`);
      }
    }

    // Current time should remain finite and non-negative
    assert(isFinite(harness.video.currentTime), 'Video currentTime must remain finite after fuzzing');
    assert(harness.video.currentTime >= 0, 'Video currentTime must not be negative');
  });

  await check('SEEK_FUZZ', 'Fuzzing seekTo() with boundaries and bad types', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 5005, type: 'movie' });
    harness.video._setDuration(3600);
    harness.video.currentTime = 100;

    harness.player.seekTo(-500);
    assert.strictEqual(harness.video.currentTime, 0, 'seekTo(-500) must clamp to 0');

    harness.player.seekTo(100000);
    assert.strictEqual(harness.video.currentTime, 3600, 'seekTo(100000) must clamp to duration (3600)');

    harness.player.seekTo(NaN);
    assert.strictEqual(harness.video.currentTime, 0, 'seekTo(NaN) should clamp safely to 0');
  });

  // ===========================================================================
  // BATCH 3: Teardown Memory Leak Audit
  // ===========================================================================
  console.log(`\n${C.bold}▶ BATCH 3: Teardown Memory Leak Audit${C.reset}`);

  await check('TEARDOWN_AUDIT', 'destroy() completely clears all timers, intervals and watchdogs', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 6001, type: 'movie' });
    harness.player.play();

    // Verify interval is active during playback
    assert(harness.player._resumeSaveTimer !== null, 'Resume tracking timer should be active');

    harness.player.destroy();

    assert.strictEqual(harness.player._resumeSaveTimer, null, 'Resume save timer must be null');
    assert.strictEqual(harness.player._streamTimeoutTimer, null, 'Watchdog timer must be null');
    assert.strictEqual(harness.player._abortController, null, 'AbortController must be null');
    assert.strictEqual(harness.osd._idleTimer, null, 'OSD idle timer must be null');
    assert.strictEqual(harness.osd._cursorTimer, null, 'OSD cursor timer must be null');
    assert.strictEqual(harness.osd._toastTimer, null, 'OSD toast timer must be null');
  });

  await check('TEARDOWN_AUDIT', 'destroy() cleans hardware decoder context and unbinds video element', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 6002, type: 'movie' });

    const videoEl = harness.video;
    assert(videoEl.querySelectorAll('track').length > 0, 'Track elements should be attached before destroy');

    harness.player.destroy();

    assert.strictEqual(videoEl.getAttribute('src'), null, 'src attribute must be removed');
    assert.strictEqual(videoEl.srcObject, null, 'srcObject must be null');
    assert.strictEqual(videoEl.querySelectorAll('track').length, 0, 'track elements must be purged');
    assert.strictEqual(harness.player.hls, null, 'HLS instance must be null');
    assert.strictEqual(videoEl._mediaState.loadCount, 1, 'video.load() must have been called to flush hardware decoder');
  });

  await check('TEARDOWN_AUDIT', 'OSD multiple init/destroy cycles does not multiply button event listeners', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 6003, type: 'movie' });
    harness.video._setDuration(3600);
    harness.video.currentTime = 500;

    // Simulate 5 destroy and re-init cycles (e.g. user entering/exiting player 5 times)
    for (let cycle = 0; cycle < 5; cycle++) {
      harness.player.destroy();
      harness.player.init();
      harness.osd.init();
    }

    // Now re-activate media
    await harness.player.loadStream({ tmdbId: 6003, type: 'movie' });
    harness.video.currentTime = 500;

    // Click forward button ONCE. If listeners leaked, currentTime will advance +50s (+10s * 5) instead of +10s!
    const forwardBtn = harness.window.document.getElementById('osd-forward-btn');
    forwardBtn.click();

    assert.strictEqual(harness.video.currentTime, 510, 'Single forward button click should advance exactly +10s (got ' + harness.video.currentTime + 's)');
  });

  // ===========================================================================
  // BATCH 4: Corrupted LocalStorage Resume Position Fuzzing
  // ===========================================================================
  console.log(`\n${C.bold}▶ BATCH 4: Corrupted LocalStorage Resume Position Fuzzing${C.reset}`);

  await check('RESUME_FUZZ', 'Malformed JSON string in localStorage is gracefully handled', async () => {
    const harness = createStressHarness();
    harness.window.localStorage.setItem('cinejoy_playback_7001_movie', '{invalid_json, missing braces');

    await harness.player.loadStream({ tmdbId: 7001, type: 'movie' });
    assert.strictEqual(harness.player.currentTime, 0, 'Malformed JSON should result in 0 currentTime');
    assert.notStrictEqual(harness.player.state, 'ERROR');
  });

  await check('RESUME_FUZZ', 'Corrupt types: null, array, boolean, NaN position in localStorage', async () => {
    const harness = createStressHarness();

    const corruptEntries = [
      JSON.stringify(null),
      JSON.stringify([1, 2, 3]),
      JSON.stringify({ position: null, duration: 7200 }),
      JSON.stringify({ position: 'corrupt_string', duration: 7200 }),
      JSON.stringify({ position: -500, duration: 7200 }),
      JSON.stringify({ position: 5, duration: 7200 }) // <= 10s threshold
    ];

    for (let i = 0; i < corruptEntries.length; i++) {
      const id = 7100 + i;
      harness.window.localStorage.setItem(`cinejoy_playback_${id}_movie`, corruptEntries[i]);
      await harness.player.loadStream({ tmdbId: id, type: 'movie' });
      assert.strictEqual(harness.video.currentTime, 0, `Entry ${i} should not restore invalid resume position`);
      harness.player.destroy();
    }
  });

  await check('RESUME_FUZZ', 'Future timestamp far beyond duration is clamped or handled', async () => {
    const harness = createStressHarness();
    harness.window.localStorage.setItem('cinejoy_playback_7200_movie', JSON.stringify({
      position: 9999999,
      duration: 7200
    }));

    await harness.player.loadStream({ tmdbId: 7200, type: 'movie' });
    assert(harness.video.currentTime <= 7200, 'Resume position must not exceed duration');
  });

  await check('RESUME_FUZZ', 'Valid resume position (>10s) successfully restores on playback start', async () => {
    const harness = createStressHarness();
    harness.window.localStorage.setItem('cinejoy_playback_7300_movie', JSON.stringify({
      position: 2450,
      duration: 7200
    }));

    await harness.player.loadStream({ tmdbId: 7300, type: 'movie' });
    harness.video._simulateCanPlay();

    assert.strictEqual(harness.video.currentTime, 2450, 'Valid resume position 2450s must be restored');
  });

  // ===========================================================================
  // BATCH 5: Stream Stall & 15000ms Watchdog Timeout Verification
  // ===========================================================================
  console.log(`\n${C.bold}▶ BATCH 5: Stream Stall & 15000ms Watchdog Timeout${C.reset}`);

  await check('WATCHDOG', 'Watchdog triggers at 15000ms if stream is stalled in RESOLVING', async () => {
    const harness = createStressHarness({
      customFetch: () => new Promise(() => {}) // Hangs indefinitely
    });

    harness.player.loadStream({ tmdbId: 8001, type: 'movie' }).catch(() => {});

    // Advance to 14,900ms - must not trigger yet
    harness.advanceClock(14900);
    assert.strictEqual(harness.player.state, 'RESOLVING');

    // Advance 200ms further (15,100ms) - must trigger timeout
    harness.advanceClock(200);
    assert.strictEqual(harness.player.state, 'ERROR');

    const errDialog = harness.window.document.getElementById('player-error-dialog');
    assert.strictEqual(errDialog.style.display, 'flex');
  });

  await check('WATCHDOG', 'Watchdog triggers at 15000ms if stream is stalled in LOADING', async () => {
    const harness = createStressHarness();
    // Resolve stream but suppress media canplay / playing
    await harness.player.loadStream({ tmdbId: 8002, type: 'movie' });
    harness.player._setState('LOADING');

    harness.advanceClock(14900);
    assert.strictEqual(harness.player.state, 'LOADING');

    harness.advanceClock(200);
    assert.strictEqual(harness.player.state, 'ERROR');
  });

  await check('WATCHDOG', 'Watchdog is cleared once playback starts and does not fire during normal play', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 8003, type: 'movie' });
    harness.video._simulateCanPlay();
    harness.video._simulatePlaying();

    assert.strictEqual(harness.player.state, 'PLAYING');

    // Advance clock past 15000ms (simulate 60 seconds of playback)
    harness.advanceClock(60000);

    // Player must remain in PLAYING state, not ERROR
    assert.strictEqual(harness.player.state, 'PLAYING', 'Player must stay PLAYING after 60s');
    assert.strictEqual(harness.player._streamTimeoutTimer, null, 'Watchdog timer must be cleared');
  });

  await check('WATCHDOG', 'Mid-stream stall shows buffering overlay and dismisses on recovery', async () => {
    const harness = createStressHarness();
    await harness.player.loadStream({ tmdbId: 8004, type: 'movie' });
    harness.video._simulateCanPlay();
    harness.video._simulatePlaying();

    // Stream encounters buffer stall
    harness.video._simulateWaiting();
    const buf = harness.window.document.getElementById('player-buffering');
    assert.strictEqual(buf.style.display, 'flex', 'Buffering overlay must be visible during stall');

    // Network recovers, playback resumes
    harness.video._simulatePlaying();
    assert.strictEqual(buf.style.display, 'none', 'Buffering overlay must be hidden after recovery');
  });

  // ===========================================================================
  // Summary & Verdict
  // ===========================================================================
  console.log(`\n${C.bold}========================================================================${C.reset}`);
  console.log(`Milestone 5 Adversarial Test Summary:`);
  console.log(`  Total Checks:   ${totalChecks}`);
  console.log(`  Passed Checks:  ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:  ${failedChecks > 0 ? C.red : C.green}${failedChecks}${C.reset}`);
  console.log(`${C.bold}========================================================================${C.reset}\n`);

  if (failedChecks > 0) {
    console.log(`${C.red}${C.bold}VERDICT: ADVERSARIAL STRESS SUITE FAILED (${failedChecks} failures)${C.reset}\n`);
    process.exit(1);
  } else {
    console.log(`${C.green}${C.bold}VERDICT: ALL ${totalChecks} ADVERSARIAL STRESS CHECKS PASSED (100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  }
}

runAdversarialSuites().catch((err) => {
  console.error('Fatal harness error:', err);
  process.exit(1);
});

